package in.paisa.personal;

import org.json.*;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;

/** Domain rules shared by all native mutation and import paths. Amounts are integer paise. */
public final class Ledger {
 public static final long MAX=100_000_000_000L;
 public static final Set<String> KINDS=new HashSet<>(Arrays.asList("expense","income","refund","lend","borrow","receive","repay","card_payment","transfer"));
 public static long amount(JSONObject o,String key,boolean zero) throws Exception {long n=new BigDecimal(o.get(key).toString()).longValueExact();if(n<(zero?0:1)||n>MAX)throw new IllegalArgumentException("Enter a valid amount");return n;}
 public static boolean active(JSONObject e){return !e.optBoolean("deleted")&&e.optString("duplicateOf").isEmpty();}
 public static boolean isLoan(String k){return k.equals("lend")||k.equals("borrow");}
 public static boolean isRepayment(String k){return k.equals("receive")||k.equals("repay");}
 public static String person(JSONObject e){return e.optString("person").trim().toLowerCase(Locale.ROOT);}
 public static JSONObject find(JSONArray rows,String id){for(int i=0;i<rows.length();i++){JSONObject e=rows.optJSONObject(i);if(e!=null&&e.optString("id").equals(id))return e;}return null;}
 public static boolean exists(JSONArray rows,String id){JSONObject e=find(rows,id);return e!=null&&!e.optBoolean("deleted");}
 public static long[] cycle(long now,int startDay){LocalDate d=Instant.ofEpochMilli(now).atZone(ZoneId.systemDefault()).toLocalDate();int n=Math.max(1,Math.min(31,startDay));YearMonth month=YearMonth.from(d);LocalDate start=month.atDay(Math.min(n,month.lengthOfMonth()));if(d.isBefore(start)){month=month.minusMonths(1);start=month.atDay(Math.min(n,month.lengthOfMonth()));}YearMonth next=month.plusMonths(1);return new long[]{start.atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli(),next.atDay(Math.min(n,next.lengthOfMonth())).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli()};}
 public static String advance(String due,String cadence,int anchor){LocalDate d=LocalDate.parse(due);if(cadence.equals("weekly"))return d.plusWeeks(1).toString();YearMonth m=YearMonth.from(d).plusMonths(cadence.equals("yearly")?12:1);return m.atDay(Math.min(Math.max(1,anchor),m.lengthOfMonth())).toString();}
 public static String nextDue(JSONObject sub,long paidAt){String due=sub.optString("nextDue");String paid=Instant.ofEpochMilli(paidAt).atZone(ZoneId.systemDefault()).toLocalDate().toString();long early=LocalDate.parse(due).toEpochDay()-LocalDate.parse(paid).toEpochDay();if(early>0&&early<=(sub.optString("cycle").equals("weekly")?2:7))return advance(due,sub.optString("cycle","monthly"),sub.optInt("anchorDay",LocalDate.parse(due).getDayOfMonth()));for(int i=0;due.compareTo(paid)<=0&&i<1200;i++)due=advance(due,sub.optString("cycle","monthly"),sub.optInt("anchorDay",LocalDate.parse(due).getDayOfMonth()));return due;}
 public static long remaining(JSONObject bill,JSONArray entries){long n=bill.optLong("amount");for(int i=0;i<entries.length();i++){JSONObject e=entries.optJSONObject(i);if(active(e)&&(e.optString("kind").equals("card_payment")&&e.optString("cardId").equals(bill.optString("id"))||e.optString("kind").equals("expense")&&e.optString("billId").equals(bill.optString("id"))))n-=e.optLong("amount");}return n;}
 public static Map<String,Long> loanBalances(JSONArray rows){
  Map<String,Long> balances=new LinkedHashMap<>();List<JSONObject> repayments=new ArrayList<>(),loans=new ArrayList<>();
  for(int i=0;i<rows.length();i++){JSONObject e=rows.optJSONObject(i);if(!active(e))continue;String k=e.optString("kind");if(isLoan(k)){balances.put(e.optString("id"),e.optLong("amount"));loans.add(e);}if(isRepayment(k))repayments.add(e);}
  loans.sort(Comparator.comparingLong(e->e.optLong("date")));repayments.sort(Comparator.comparingLong(e->e.optLong("date")));
  for(JSONObject r:repayments){String id=r.optString("loanId");if(id.isEmpty())continue;JSONObject l=find(rows,id);if(l==null||!active(l)||!l.optString("kind").equals(r.optString("kind").equals("receive")?"lend":"borrow")||!person(l).equals(person(r)))throw new IllegalArgumentException("Original loan does not match repayment");long n=balances.get(id)-r.optLong("amount");if(n<0)throw new IllegalArgumentException("Repayment exceeds original loan");balances.put(id,n);}
  for(JSONObject r:repayments){if(!r.optString("loanId").isEmpty())continue;long n=r.optLong("amount");for(JSONObject l:loans){if(!person(l).equals(person(r))||!l.optString("kind").equals(r.optString("kind").equals("receive")?"lend":"borrow"))continue;long use=Math.min(n,balances.get(l.optString("id")));balances.put(l.optString("id"),balances.get(l.optString("id"))-use);n-=use;if(n==0)break;}if(n>0)throw new IllegalArgumentException("Repayments would exceed recorded loans. Adjust the repayment first.");}
  return balances;
 }
 public static void validate(JSONObject state) throws Exception {
  JSONArray entries=state.getJSONArray("entries"),accounts=state.getJSONArray("accounts"),bills=state.getJSONArray("bills"),subs=state.getJSONArray("subscriptions");
  if(entries.length()>100000)throw new IllegalArgumentException("Backup has too many entries");
  for(String table:Arrays.asList("entries","accounts","bills","subscriptions")){Set<String> ids=new HashSet<>();JSONArray rows=state.getJSONArray(table);for(int i=0;i<rows.length();i++){JSONObject e=rows.getJSONObject(i);String id=e.optString("id");if(id.isEmpty()||id.length()>120||!ids.add(id))throw new IllegalArgumentException("Invalid or repeated ID in "+table);}}
  for(int i=0;i<entries.length();i++){JSONObject e=entries.getJSONObject(i);amount(e,"amount",false);String k=e.optString("kind");if(!KINDS.contains(k))throw new IllegalArgumentException("Choose a valid transaction type");if(e.optString("title").trim().isEmpty()||e.optString("title").length()>100||e.optString("note").length()>1000||e.optString("person").length()>80||e.optString("category").length()>40)throw new IllegalArgumentException("Check title, note and category lengths");long date=e.optLong("date");if(date<946684800000L||date>System.currentTimeMillis()+86400000L)throw new IllegalArgumentException("Choose a valid transaction date");if(!active(e))continue;if((isLoan(k)||isRepayment(k))&&person(e).isEmpty())throw new IllegalArgumentException("Whose payment is this?");if(!exists(accounts,e.optString("accountId")))throw new IllegalArgumentException("Payment account not found");if(k.equals("transfer")&&!e.optBoolean("unresolvedTransfer")){if(e.optString("accountId").equals(e.optString("toAccountId"))||!exists(accounts,e.optString("toAccountId")))throw new IllegalArgumentException("Choose two different transfer accounts");}if(k.equals("card_payment")&&!e.optString("toAccountId").isEmpty()&&(e.optString("accountId").equals(e.optString("toAccountId"))||!exists(accounts,e.optString("toAccountId"))||!find(accounts,e.optString("toAccountId")).optString("type").equals("credit")))throw new IllegalArgumentException("Card payment destination must be a different credit-card account");if(!e.optString("billId").isEmpty()&&(!exists(bills,e.optString("billId"))||!k.equals("expense")||!find(bills,e.optString("billId")).optString("kind").equals("utility")))throw new IllegalArgumentException("Utility bill link is invalid");if(!e.optString("loanId").isEmpty()&&!isRepayment(k))throw new IllegalArgumentException("Only repayments can link to a loan");if(!e.optString("cardId").isEmpty()&&(!exists(bills,e.optString("cardId"))||!k.equals("card_payment")))throw new IllegalArgumentException("Linked statement bill not found");if(!e.optString("subId").isEmpty()&&!exists(subs,e.optString("subId")))throw new IllegalArgumentException("Linked subscription not found");}
  loanBalances(entries);
  for(int i=0;i<accounts.length();i++){JSONObject a=accounts.getJSONObject(i);if(a.optString("name").trim().isEmpty()||a.optString("name").length()>80||!Arrays.asList("bank","cash","credit").contains(a.optString("type")))throw new IllegalArgumentException("Invalid account");long n=a.optLong("opening");if(n < -MAX||n>MAX)throw new IllegalArgumentException("Invalid opening balance");}
  for(int i=0;i<bills.length();i++){JSONObject b=bills.getJSONObject(i);amount(b,"amount",false);LocalDate.parse(b.getString("due"));if(b.optString("name").trim().isEmpty()||b.optString("name").length()>80||remaining(b,entries)<0)throw new IllegalArgumentException("Check bill amount and payments");}
  for(int i=0;i<subs.length();i++){JSONObject s=subs.getJSONObject(i);amount(s,"amount",false);LocalDate.parse(s.getString("nextDue"));if(s.optString("name").trim().isEmpty()||s.optString("name").length()>80||!Arrays.asList("weekly","monthly","yearly").contains(s.optString("cycle")))throw new IllegalArgumentException("Check subscription details");}
  JSONObject settings=state.getJSONObject("settings");if(settings.optInt("cycleStartDay",1)<1||settings.optInt("cycleStartDay",1)>31)throw new IllegalArgumentException("Month start day must be 1–31");amount(settings,"monthBudget",true);JSONObject limits=settings.optJSONObject("categoryBudgets");if(limits!=null)for(Iterator<String> keys=limits.keys();keys.hasNext();){String k=keys.next();amount(limits,k,true);}
 }
}
